/* [sarlavha, izoh, savol, [to'g'ri javob, noto'g'ri, noto'g'ri]]. Variantlar tartibi kodda aralashtiriladi. */
export const textUz: Record<string, RuleTuple> = {
  // Umumiy qoidalar
  "2": ["O'ng tomonlama harakat", "O'zbekistonda transport vositalari yo'lning o'ng tomonida harakatlanadi.", "O'zbekistonda transport vositalari yo'lning qaysi tomonida harakatlanadi?", ["O'ng tomonda", "Chap tomonda", "Istalgan tomonda"]],
  "3": ["Qoidalarni bilish va ularga amal qilish", "Yo'l harakati ishtirokchilari Qonunni, Qoidalarni, svetofor ishoralarini, belgilar va chiziqlarni bilishi va ularga amal qilishi, tartibga soluvchilarning vakolati doirasidagi ko'rsatmalarini so'zsiz bajarishi shart.", "Yo'l harakati ishtirokchilari kimning ko'rsatmasini so'zsiz bajarishi shart?", ["Vakolati doirasida harakat qilayotgan tartibga soluvchining", "Orqadagi istalgan haydovchining", "Faqat maxsus bo'yoqli mashinalarning"]],
  "4": ["Xalaqit bermang va xavf tug'dirmang", "Yo'l harakati ishtirokchilari boshqalarga xalaqit bermasligi va xavf tug'dirmasligi kerak. To'siq yaratgan shaxs uni tezda bartaraf etishi yoki barcha vosita bilan ogohlantirib, IIOga xabar berishi shart.", "Siz yo'lda to'siq yaratdingiz va uni olib tashlay olmaysiz. Nima qilasiz?", ["Barcha vositalar bilan ogohlantirib, IIOga xabar beraman", "Indamay ketaman", "Qorong'i tushishini kutaman"]],
  "d-yield": ["Yo'l berish nimani anglatadi", "Yo'l berish — imtiyozli ishtirokchini yo'nalishi yoki tezligini o'zgartirishga majbur qilishi mumkin bo'lsa, harakat yoki manyovrni davom ettirmaslik yoki boshlamaslik talabi.", "Yo'l berish nimani anglatadi?", ["Imtiyozli ishtirokchini tezligini yoki yo'nalishini o'zgartirishga majbur qilsangiz, harakatlanmaslik", "Chiroqni miltillatib birinchi o'tish", "Sekinlashib, lekin hech qachon to'xtamaslik"]],
  "d-main": ["Asosiy va ikkinchi darajali yo'l", "Qattiq qoplamali yo'l tuproqli yoki shag'alli yo'lga nisbatan asosiy hisoblanadi. Ikkinchi darajali yo'lning chorrahaga tutash qismining qoplamali bo'lishi uni asosiy yo'l bilan teng huquqli qilmaydi.", "Ikkinchi darajali yo'lning chorraha oldidagi qismi asfaltlangan. U asosiy yo'lga tenglashadimi?", ["Yo'q, u ikkinchi darajali bo'lib qoladi", "Ha, doim", "Faqat kunduzi"]],
  "d-stop": ["To'xtash va to'xtab turish", "To'xtash — harakatni 10 daqiqagacha to'xtatish. To'xtab turish — yo'lovchi chiqarish yoki tushirish, yuk ortish yoki tushirish bilan bog'liq bo'lmagan hollarda harakatni 10 daqiqadan ko'proq atayin to'xtatish.", "Harakatni qancha muddatgacha to'xtatish «to'xtash» hisoblanadi?", ["10 daqiqagacha", "1 daqiqagacha", "1 soatgacha"]],
  "d-vis": ["Yetarlicha ko'rinmaslik", "Yetarlicha ko'rinmaslik — yomg'ir, qor, tuman yoki g'ira-shira vaqtda yo'lning ko'rinish masofasi 300 metrdan kam bo'lishi.", "Ko'rinish masofasi qanchadan kam bo'lsa, u yetarli emas hisoblanadi?", ["300 m", "100 m", "1 km"]],

  // Haydovchilar vazifalari
  "7": ["Yonda olib yuriladigan hujjatlar", "Tegishli toifadagi haydovchilik guvohnomasi, transport vositasini ro'yxatdan o'tkazish guvohnomasi va sug'urta polisini (elektron ham bo'ladi) yonda olib yuring va IIO talabi bilan ko'rsating.", "Haydovchi qaysi hujjatlarni yonida olib yurishi shart?", ["Guvohnoma, ro'yxatdan o'tish guvohnomasi va sug'urta polisi", "Faqat pasport", "Faqat guvohnoma"]],
  "8": ["Guvohnoma toifalari", "Transport vositangiz turiga mos guvohnoma kerak. «B» toifasi haydovchidan tashqari 8 tadan ko'p bo'lmagan o'rindiqli, to'liq vazni 3 500 kg gacha bo'lgan transport vositalarini qamrab oladi.", "«B» toifasi to'liq vazni qanchagacha bo'lgan transport vositalarini qamrab oladi?", ["3 500 kg gacha", "2 000 kg gacha", "5 500 kg gacha"]],
  "9": ["Xavfsizlik kamari va motoshlem", "Haydovchi va old o'rindiqdagi yo'lovchilar harakatni boshlashdan oldin kamarlarini taqishi shart. Mototsikl, moped va skuterdagilar motoshlem kiyib, uni qadab olishi kerak.", "Haydovchi xavfsizlik kamarini qachon taqishi kerak?", ["Harakatni boshlashdan oldin", "Faqat aholi punktidan tashqarida", "Faqat kechasi"]],
  "11": ["Haydovchining majburiyatlari", "Yo'lga chiqishdan oldin transport vositasini tekshiring, harakatlanishdan oldin yo'lovchilar joylashganiga va eshiklar yopilganiga ishonch hosil qiling, piyodalar, bolalar, nogironlar, qariyalar va velosipedchilarga nisbatan ehtiyot bo'ling.", "Harakatni boshlashdan oldin haydovchi nimaga ishonch hosil qilishi kerak?", ["Yo'lovchilar joylashgan va eshiklar yopilgan", "Radio yoqilgan", "Derazalar ochiq"]],
  "12": ["Alkogol, giyohvand moddalar, charchoq", "Mast holatda, giyohvand moddalar yoki sezgirlikni susaytiradigan dorilar ta'sirida, xavfli charchoq yoki betoblikda boshqarish taqiqlanadi. Bunday shaxsga yoki guvohnomasi yo'q shaxsga transport vositasini topshirish ham taqiqlanadi.", "Mast do'stingizga mashinangizni haydashga berish mumkinmi?", ["Yo'q, bu taqiqlangan", "Ha, qisqa masofaga", "Ha, qorong'i bo'lsa"]],
  "12p": ["Telefon va ekranlar", "Boshqarish paytida telefondan foydalanish taqiqlanadi (qo'lsiz aloqa bundan mustasno). Salon oldidagi ekranda tele va videomahsulotlarni ko'rish taqiqlanadi.", "Boshqarish paytida telefondan foydalanish mumkin…", ["Faqat qo'llarni ishlatmasdan", "Doim", "Faqat chorrahada"]],

  // YTH
  "13": ["Yo'l-transport hodisasidan keyin", "Darhol to'xtang, avariya chiroqlarini yoqing va avariya belgisini qo'ying, birinchi yordam ko'rsating, tez yordam va qutqaruv xizmatini chaqiring, IIOga xabar bering. Harakatga xalaqit bersangiz, joylashuvni qayd etgach, qatnov qismini bo'shating.", "Hodisadan keyin haydovchi birinchi nima qilishi kerak?", ["To'xtab, avariya chiroqlarini yoqish va belgini qo'yish", "Haydab ketish", "Avval mashinalarni yo'l chetiga olish"]],

  // Piyodalar
  "15": ["Piyodalar qayerda yuradi", "Trotuar va yo'lkalardan, ular bo'lmasa yo'l yoqasidan yuring. Qatnov qismi chetida transport harakatiga qarama-qarshi yo'nalishda yuring.", "Trotuar bo'lmasa, yo'l chetida qaysi yo'nalishda yurish kerak?", ["Transportga qarama-qarshi yo'nalishda", "Transport bilan bir yo'nalishda", "O'rtada"]],
  "16": ["Piyodalar jamlanmasi", "Qatnov qismida tashkiliy jamlanma bir qatorda to'rt kishidan ko'p bo'lmay, o'ng tomondan yuradi, old va orqasida chapdan qizil bayroqcha (qorong'ida oq va qizil chiroq) bilan.", "Qatnov qismida tashkiliy jamlanma bir qatorda eng ko'pi bilan nechta kishi yuradi?", ["To'rttagacha", "Sakkiztagacha", "Istalgancha"]],
  "17": ["Qayerdan kesib o'tish", "Piyodalar o'tish joylaridan, yer osti va yer usti o'tish joylaridan kesib o'ting. Ular bo'lmasa, chorrahada trotuar chizig'i bo'ylab yoki yo'l ikki tomonga yaxshi ko'rinadigan joydan to'g'ri burchak ostida kesib o'ting.", "O'tish joyi yaqin bo'lmasa, yo'lni qanday kesib o'tish kerak?", ["Yo'l yaxshi ko'rinadigan joydan to'g'ri burchak ostida", "Diagonal bo'ylab", "Turgan mashina orqasidan"]],
  "18": ["Ishoralarga amal qiling", "Harakat tartibga solingan joylarda piyodalar tartibga soluvchi yoki piyodalar svetofori, ular bo'lmasa transport svetofori ishoralariga amal qiladi.", "Tartibga solingan joyda piyodalar qaysi ishoraga amal qiladi?", ["Tartibga soluvchi yoki piyodalar svetoforiga", "Faqat o'z xohishiga", "Eng yaqin mashinaga"]],
  "19": ["Xavfsiz kesib o'tish", "Tartibga solinmagan o'tish joyida transport masofasi va tezligini baholang. Qatnov qismida telefon, video, o'qish taqiqlanadi. To'xtagan avtobusning orqasidan, tramvayning oldidan o'ting.", "To'xtagan avtobus yonida yo'lni qayerdan kesib o'tish kerak?", ["Orqasidan", "Oldidan", "Tagidan"]],
  "20": ["Yo'lda to'xtab qolmang", "Zaruratsiz qatnov qismida to'xtamang. O'tishga ulgurmasangiz, xavfsizlik orolchasida yoki oqimlarni ajratuvchi chiziqda to'xtang.", "Kesib o'tishga ulgurmadingiz. Qayerda kutasiz?", ["Xavfsizlik orolchasida yoki ajratuvchi chiziqda", "Tramvay yo'lida", "Mashina oldida"]],
  "21": ["Tezkor va maxsus xizmatlar", "Mayoqcha va sirenali tezkor transport yaqinlashsa, qatnov qismiga chiqmang. Unda bo'lsangiz, yo'l bering va darhol bo'shating.", "Sirenali tez yordam yaqinlashmoqda. Yo'ldagi piyoda nima qiladi?", ["Yo'l berib, qatnov qismini darhol bo'shatadi", "Tez kesib o'tadi", "Joyida turadi"]],
  "22": ["Transport bekatlari", "Yo'nalishli transportni baland maydonchada yoki trotuarda kuting. Maydonchasiz bekatda transport to'liq to'xtagandan keyingina yo'lga chiqing, tushgach darhol qatnov qismini bo'shating.", "Maydonchasiz bekatda minish uchun qachon yo'lga chiqish mumkin?", ["Transport to'liq to'xtagandan keyin", "U hali harakatlanayotganda", "U ko'ringan zahoti"]],

  // Yo'lovchilar
  "23": ["Chiqish va tushish", "Yo'lovchilar faqat transport to'liq to'xtagandan keyin, trotuar yoki yo'l yoqasi tomondan chiqadi va tushadi, harakatdan oldin kamar yoki motoshlemni taqadi.", "Yo'lovchilar transport vositasiga qachon chiqishi va tushishi mumkin?", ["Faqat to'liq to'xtagandan keyin", "Sekinlashayotganda", "Istalgan vaqt"]],
  "24": ["Yo'lovchilarga taqiqlar", "Yo'lovchilar haydovchini chalg'itmasligi, yuk mashinasi kuzovida tik turmasligi, bortda o'tirmasligi, harakat paytida eshik ochmasligi va tana qismlarini chiqarmasligi kerak.", "Yo'lovchiga nima taqiqlanadi?", ["Harakat paytida eshikni ochish", "Kamar taqish", "Orqa o'rindiqda o'tirish"]],

  // Maxsus transport
  "25": ["Maxsus transport imtiyozlari", "Mayoqcha va sirena yoqilgan tezkor va maxsus transport xavfsizlikni ta'minlab, ayrim qoidalardan chetga chiqishi mumkin va imtiyozdan faqat unga yo'l berilayotganiga ishonch hosil qilgach foydalanadi.", "Maxsus transport imtiyozdan faqat qachon foydalanishi mumkin?", ["Mayoqcha va sirena yoqilgan, unga yo'l berilayotgan bo'lsa", "Faqat guvohnomasi bo'lsa", "100 km/soatdan tez yursa"]],
  "26": ["Maxsus transportga yo'l bering", "Ko'k yoki qizil mayoqchali va sirenali transportga hamda uning kuzatuvidagi mashinalarga yo'l bering. Ularni quvib o'tish taqiqlanadi.", "Orqadan mayoqcha va sirenali tez yordam yaqinlashmoqda. Nima qilasiz?", ["Yo'l beraman", "Quvib o'taman", "Tezlashaman"]],
  "27": ["To'xtab turgan maxsus transport", "Mayoqchasi yoqilgan to'xtab turgan transportga yaqinlashganda, kerak bo'lsa darhol to'xtay oladigan darajada tezlikni kamaytiring.", "Mayoqchasi yoqilgan to'xtab turgan militsiya mashinasiga yaqinlashyapsiz. Nima qilasiz?", ["Darhol to'xtay oladigan darajada tezlikni kamaytiraman", "Tezlikni saqlayman", "Signal chalaman"]],
  "28": ["Zarg'aldoq va sariq mayoqchalar", "Zarg'aldoq yoki sariq mayoqchalar xavf haqida ogohlantiradi (yo'l ishlari, katta o'lchamli yuk, shatakka olish). Ular imtiyoz bermaydi.", "Sariq mayoqcha transport vositasiga imtiyoz beradimi?", ["Yo'q, faqat ogohlantiradi", "Ha, doim", "Ha, asosiy yo'lda"]],

  // Ishoralar
  "31": ["Doirasimon svetofor: yashil va sariq", "Yashil harakatga ruxsat beradi. Miltillovchi yashil ham ruxsat beradi, lekin tugayotganidan ogohlantiradi. Sariq harakatni taqiqlaydi (42-banddagi hollardan tashqari) va almashuvdan ogohlantiradi.", "Sariq ishora nimani anglatadi?", ["Harakat taqiqlanadi, ishora almashadi", "Tezlashish", "Erkin harakatlanish"]],
  "31r": ["Doirasimon svetofor: qizil va miltillovchi", "Qizil va miltillovchi qizil harakatni taqiqlaydi. Qizil va sariq birga yonsa taqiqlaydi va yashil tez orada yonishidan xabar beradi. Miltillovchi sariq ehtiyotkorlik bilan harakatlanishga ruxsat beradi va tartibga solinmagan chorraha yoki o'tish joyidan ogohlantiradi.", "Miltillovchi sariq ishora nimani anglatadi?", ["Ehtiyotkor harakatlaning, chorraha yoki o'tish joyi tartibga solinmagan", "Bir daqiqa to'xtang", "Harakat taqiqlanadi"]],
  "32": ["Strelkali svetofor", "Strelkali ishoralar faqat ko'rsatilgan yo'nalishga ta'sir qiladi. Chapga burilish strelkasi belgi taqiqlamasa, qayrilib olishga ham ruxsat beradi. Qo'shimcha tarmoq o'chirilgan bo'lsa, o'sha yo'nalish taqiqlanadi.", "Chapga yashil strelka yana nimaga ruxsat beradi?", ["Taqiqlanmagan bo'lsa, qayrilib olishga", "To'xtab turishga", "Quvib o'tishga"]],
  "34": ["Piyoda va velosiped svetoforlari", "Piyoda tasvirli ishora faqat piyodalarga ta'sir qiladi. Velosiped tasvirli ishora velosipedchilar va individual harakatlanish vositalarini boshqargan shaxslarga. Yashil ruxsat beradi, qizil taqiqlaydi.", "Piyoda tasvirli ishora kimga taalluqli?", ["Faqat piyodalarga", "Barcha transportga", "Faqat yengil mashinalarga"]],
  "35": ["Reversiv svetoforlar", "Reversiv tasma ustida qizil X taqiqlaydi, yashil strelka ruxsat beradi. 1.9 chiziq bilan belgilangan tasma ustidagi o'chirilgan svetofor unga kirishni taqiqlaydi.", "Tasma ustidagi qizil X nimani anglatadi?", ["Tasma siz uchun yopiq", "Tasma bo'sh", "Tezlik cheklovi"]],
  "37": ["Temir yo'l kesishmasidagi svetofor", "Miltillovchi oq chiroq o'tishga ruxsat beradi. Miltillovchi qizil taqiqlaydi, tovushli ishora ham berilishi mumkin. Ishoralar o'chiq bo'lsa va poyezd ko'rinmasa, o'tish mumkin.", "Temir yo'l kesishmasida miltillovchi qizil chiroq nimani anglatadi?", ["O'tish taqiqlanadi", "O'tishga ruxsat", "Faqat sekinlashish"]],
  "38": ["Tartibga soluvchi ishoralari", "Qo'llar yonga uzatilsa: yon tomonlardan transport to'g'riga va o'ngga, piyodalar kesib o'tadi, old va orqadan hamma to'xtaydi. O'ng qo'l oldinga: chapdan barcha yo'nalishlarga, oldidan faqat o'ngga. Qo'l yuqoriga: hamma to'xtaydi.", "Tartibga soluvchi qo'lini yuqoriga ko'tardi. Bu nimani anglatadi?", ["Barcha transport va piyodalar to'xtashi kerak", "To'g'riga yuring", "Faqat o'ngga buriling"]],
  "39": ["Talab bo'yicha to'xtash", "Tartibga soluvchi yoki IIO xodimi qo'l ishorasi yoki ovoz kuchaytirgich bilan to'xtashni talab qilsa, ko'rsatilgan joyda to'xtang.", "IIO xodimi to'xtashni talab qildi. Nima qilasiz?", ["Ko'rsatilgan joyda to'xtayman", "Sekinlashib davom etaman", "Keyingi chorrahada to'xtayman"]],
  "41": ["Taqiqlovchi ishorada qayerda to'xtash", "To'xtash chizig'i oldida to'xtang, transportning eng oldingi nuqtasi chiziqdan chiqmasin. Chiziq bo'lmasa, kesishayotgan qatnov qismi chetida piyodalarga xalaqit bermay, yoki svetofor yoki tartibga soluvchi oldida to'xtang.", "To'xtash chizig'i bor joyda qizil chiroqda qayerda to'xtaysiz?", ["Chiziq oldida, uning ustiga chiqmasdan", "Aynan chiziq ustida", "Chiziqdan o'tib, o'tish joyi oldida"]],
  "42": ["Sariq va keskin tormoz", "Sariq yonganda yoki tartibga soluvchi qo'lini ko'targanda keskin tormozlamasdan to'xtay olmasangiz, harakatni davom ettirishingiz mumkin. Qatnov qismidagi piyodalar uni bo'shatishi kerak.", "Sariq chiroqda qachon davom etish mumkin?", ["Faqat keskin tormozlamasdan to'xtay olmasangiz", "Doim", "Faqat avtomagistralda"]],
  "43": ["Qaysi ishora ustun", "Tartibga soluvchining ko'rsatmasi svetofor, belgilar va chiziqlardan ustun. Svetofor imtiyoz belgilaridan ustun. Svetofor ishlamasa, ko'ndalang svetofor ham ishlamayotganiga ishonch hosil qilgach davom eting.", "Svetoforda qizil, lekin tartibga soluvchi o'tishga ishora qilmoqda. Kimga amal qilasiz?", ["Tartibga soluvchiga", "Svetoforga", "Oldingi mashinaga"]],

  // Ogohlantiruvchi ishoralar
  "44": ["Ogohlantiruvchi ishoralar", "Ogohlantiruvchi ishoralar: burilish chiroqlari yoki qo'l ishoralari, to'xtash chiroqlari, tovushli ishora, farani yoqib-o'chirish va kunduzi yaqinni yorituvchi fara.", "Quyidagilardan qaysi biri ogohlantiruvchi ishora?", ["Burilish ko'rsatkichi", "Oyna tozalagich", "Radio"]],
  "45": ["Manyovrdan oldin ishora bering", "Harakatni boshlash, qayta tizilish, burilish va to'xtashdan oldin yo'nalishni ko'rsating. Chiroqsiz qo'l bilan: chapga — chap qo'l yonga yoki o'ng qo'l tirsakdan bukilib yuqoriga, o'ngga — o'ng qo'l yonga yoki chap qo'l bukilib yuqoriga.", "Burilish ishorasi qachon beriladi?", ["Manyovrdan oldin", "Burilish paytida", "Burilgandan keyin"]],
  "46": ["Ishoraning vaqti", "Ishorani manyovrdan oldinroq bering va tugagach darhol o'chiring. Ishora oldin o'tish huquqini bermaydi va ehtiyot choralaridan ozod etmaydi.", "Burilish ishorasi o'tish huquqini beradimi?", ["Yo'q, ehtiyot choralarini ko'rish shart", "Ha", "Ha, kechasi"]],
  "47": ["Yo'nalish o'zgartirishdan oldin tekshiring", "Yo'nalishni o'zgartirishdan oldin orqada kelayotgan sizni quvib o'tayotgani yoki boshlagani yo'qligiga va hech kimga xalaqit bermayotganingizga ishonch hosil qiling.", "Qatorni almashtirishdan oldin nimaga ishonch hosil qilishingiz kerak?", ["Orqadagi sizni quvib o'tmayotgan va xalaqit bermayotganingizga", "Yo'l nam ekaniga", "Signal ishlashiga"]],
  "48": ["Tovushli ishora", "Tovushli ishora faqat aholi punktlaridan tashqarida quvib o'tishdan ogohlantirish uchun va yo'l-transport hodisasining oldini olish uchun qo'llaniladi. Boshqa hollarda taqiqlanadi.", "Aholi punktida signalni qachon chalish mumkin?", ["Faqat hodisaning oldini olish uchun", "Salomlashish uchun", "Oldingi mashinani shoshirish uchun"]],
  "50": ["Avariya ishorasi", "Avariya chiroqlarini hodisa sodir bo'lganda, taqiqlangan joyda majburiy to'xtaganda, fara ko'zni qamashtirganda, shatakka olishda va «Bolalarni tashish» belgisi bor transportga bolalar chiqayotganda yoki tushayotganda yoqing.", "Avariya ishorasi qachon yoqilishi kerak?", ["Hodisadan keyin yoki taqiqlangan joyda majburiy to'xtaganda", "Do'kon oldida to'xtab turganda", "Har bir burilishda"]],
  "51": ["Avariya sababli to'xtash belgisi", "Transport to'satdan to'xtasa, avariya chiroqlarini yoqing, ishlamasa belgini darhol qo'ying. Belgi aholi punktlarida transportdan kamida 15 m, aholi punktlaridan tashqarida kamida 30 m masofada bo'lishi kerak.", "Aholi punktidan tashqarida belgi orqada qancha masofada qo'yiladi?", ["Kamida 30 m", "Kamida 15 m", "Kamida 5 m"]],

  // Manyovrlar
  "53": ["Manyovr xavfsiz bo'lsin", "Harakatni boshlash, qayta tizilish, burilish, orqaga yurish, quvib o'tish va to'xtashdan oldin manyovr boshqalarga xavf tug'dirmasligiga ishonch hosil qiling.", "Har qanday manyovrdan oldin nimaga ishonch hosil qilish kerak?", ["U boshqalarga xavf tug'dirmasligiga", "Birinchi bo'lishingizga", "Sizni hech kim ko'rmasligiga"]],
  "54": ["Yondosh hududdan chiqish", "Hovli yoki boshqa yondosh hududdan chiqayotganda yo'ldagi piyodalar va transportga, shuningdek chiqishda yo'nalishingizni kesib o'tayotganlarga yo'l bering.", "Hovlidan yo'lga chiqayotganda kimga yo'l berasiz?", ["Yo'ldagi barchaga", "Hech kimga", "Faqat yuk mashinalariga"]],
  "55": ["Qayta tizilish", "Qatorni almashtirganda yo'lakay to'g'ri ketayotgan transportga yo'l bering. Bir yo'nalishdagilar bir vaqtda qayta tizilsa, o'ng tomondagiga yo'l bering.", "Ikki mashina bir yo'nalishda bir vaqtda qatorni almashtiryapti. Kim yo'l beradi?", ["O'ng tomonida ikkinchi mashina bo'lgani", "Tezroq ketayotgani", "Yoshi kattaroq haydovchi"]],
  "56": ["Burilishdan oldin joylashish", "O'ngga, chapga burilish yoki qayrilib olishdan oldin qatnov qismining shu yo'nalishga mos eng chetki holatini oldindan egallang (aylanma chorrahaga kirish bundan mustasno).", "Burilishdan oldin nima qilish kerak?", ["Mos qatorni oldindan egallash", "Istalgan qatordan burilish", "O'rta qatorda sekinlashish"]],
  "57": ["Burilish va o'z tomoningiz", "Chorrahadan chiqayotganda qarama-qarshi tomonga o'tib ketmaslik uchun buriling. O'ngga burilishda iloji boricha qatnov qismining o'ng chetiga yaqin bo'ling.", "O'ngga burilishda mashina qayerda bo'lishi kerak?", ["Imkon qadar o'ng chetga yaqin", "Yo'lning o'rtasida", "Qatnov qismining chap tomonida"]],
  "59": ["Chorrahadan tashqarida burilish", "Chorrahadan tashqarida chapga burilayotgan yoki qayrilib olayotgan haydovchi qarama-qarshi transportga va bir yo'nalishdagi tramvayga yo'l beradi.", "Chorrahadan tashqarida chapga burilganda kimga yo'l berasiz?", ["Qarama-qarshi transportga va bir yo'nalishdagi tramvayga", "Hech kimga", "Faqat piyodalarga"]],
  "60": ["Qoida yo'q bo'lsa o'ngdagiga yo'l bering", "Yo'nalishlar kesishganda va o'tish navbati Qoidalarda ko'zda tutilmagan bo'lsa, o'ng tomondan yaqinlashayotgan transportga yo'l bering.", "Yo'llar kesishgan, navbat belgilanmagan. Kimga yo'l berasiz?", ["O'ng tomondan kelayotganga", "Chap tomondan kelayotganga", "Kattaroq transportga"]],
  "62": ["Qayrilib olish taqiqlangan joylar", "Qayrilib olish piyodalar o'tish joylarida, tunnellarda, ko'prik, yo'l o'tkazgich va estakadalarda va ularning ostida (belgi bilan ruxsat berilganidan tashqari), temir yo'l kesishmalarida va ko'rinish 100 m dan kam joylarda taqiqlanadi.", "Qayrilib olish qayerda taqiqlanadi?", ["Piyodalar o'tish joyida", "Keng bo'sh ko'chada", "Hovlida"]],
  "63": ["Orqaga harakatlanish", "Orqaga harakatlanishda xavfsizlikni ta'minlang va boshqalarga xalaqit bermang, zarur bo'lsa boshqalar yordamidan foydalaning. Chorrahalarda va 62-bandga ko'ra qayrilib olish mumkin bo'lmagan joylarda orqaga yurish taqiqlanadi.", "Orqaga harakatlanish qayerda taqiqlanadi?", ["Chorrahalarda", "To'xtab turish joyida", "Sokin ko'chada"]],

  // Yo'lda joylashuv
  "64": ["Qarama-qarshi yo'nalish yarmi", "Ikki tomonlama yo'lda chap yarmi qarama-qarshi harakat uchun. Tramvay yo'li, ajratuvchi tasma, uzluksiz 1.1 yoki 1.3 chiziq yoki uzuq tomoni chapda joylashgan 1.11 chiziq bilan ajratilgan joyda unga chiqish taqiqlanadi.", "1.1 yoki 1.3 chiziq oqimlarni ajratgan joyda qarama-qarshi yarmga chiqish mumkinmi?", ["Yo'q", "Ha, yo'l bo'sh bo'lsa", "Ha, quvib o'tish uchun"]],
  "65": ["To'rt va undan ortiq tasmali yo'llar", "Harakat ikki tomonlama, to'rt va undan ortiq tasmali yo'llarda qarama-qarshi yo'nalish tasmalariga chiqish taqiqlanadi.", "To'rt tasmali ikki tomonlama yo'lda qarama-qarshi tasmadan yurish mumkinmi?", ["Yo'q", "Ha, quvib o'tish uchun", "Ha, kechasi"]],
  "66": ["Uch tasmali yo'llar", "Chiziqlar bilan belgilangan uch tasmali ikki tomonlama yo'lda o'rta tasma umumiy bo'lib, faqat quvib o'tish, aylanib o'tish, chapga burilish va qayrilib olish uchun. Qarama-qarshi chetki chap tasmani egallash taqiqlanadi.", "Uch tasmali ikki tomonlama yo'lda o'rta tasma nima uchun ishlatiladi?", ["Quvib o'tish, aylanib o'tish, chapga burilish va qayrilib olish uchun", "Oddiy harakatlanish uchun", "To'xtab turish uchun"]],
  "67": ["O'ngroq yuring", "Aholi punktlaridan tashqarida va yuqori tezlik ruxsat etilgan joylarda iloji boricha o'ng chetga yaqin yuring. O'ng tasmalar bo'sh bo'lsa, chap tasmalarni egallash taqiqlanadi.", "Aholi punktidan tashqarida o'ng tasma bo'sh bo'lsa, qayerda yurasiz?", ["O'ng tasmada", "Chap tasmada", "Chiziq ustida"]],
  "68": ["Sekin harakatlanuvchilar", "Tezligini 40 km/soatdan oshira olmaydigan yoki oshirmasligi kerak bo'lgan transport quvib o'tish, aylanib o'tish, chapga burilish, qayrilib olishdan va ruxsat etilgan joyda to'xtashdan tashqari chetki o'ng tasmada yuradi.", "Tezligi 40 km/soatdan oshmaydigan transport qaysi tasmada yurishi kerak?", ["Chetki o'ng tasmada", "O'rta tasmada", "Chap tasmada"]],
  "69": ["Tramvay yo'llari", "Chapdagi tramvay yo'lidan bir yo'nalishda, boshqa tasmalar band bo'lganda tramvayga xalaqit bermasdan yurish mumkin. Qarama-qarshi yo'nalishdagi tramvay yo'lidan yurish taqiqlanadi.", "Tramvay yo'lidan tramvayga qarshi yo'nalishda yurish mumkinmi?", ["Yo'q, taqiqlangan", "Ha, tramvay yaqin bo'lmasa", "Ha, kechasi"]],
  "70": ["O'z tasmangizda yuring", "Qatnov qismi chiziqlar bilan tasmalarga ajratilgan bo'lsa, qat'iy o'z tasmangizda yuring. Uzuq chiziqlarni faqat qayta tizilishda kesib o'tish mumkin.", "Tasma uzuq chiziqlarini qachon kesib o'tish mumkin?", ["Faqat qayta tizilishda", "Xohlagan paytda", "Hech qachon"]],
  "71": ["Reversiv yo'lga burilish", "Reversiv yo'lga burilganda chorrahadan chetki o'ng qatorda chiqing, boshqa tasmalarga faqat xavfsizligiga ishonch hosil qilgach o'ting.", "Reversiv yo'lga burilganda qaysi tasmaga chiqasiz?", ["Chetki o'ng tasmaga", "Chap tasmaga", "Istalgan tasmaga"]],
  "72": ["Trotuarda yurmang", "Mexanik transport vositalariga ajratuvchi mintaqalar, yo'l yoqalari, trotuarlar, piyoda va velosiped yo'lkalari va yashil hududlarda harakatlanish taqiqlanadi (Qoidalarda ruxsat berilgan hollardan tashqari).", "Mashinada trotuarda yurish mumkinmi?", ["Yo'q, Qoidalarda ruxsat berilgan hollardan tashqari", "Ha, tirbandlikni aylanib o'tish uchun", "Ha, kechasi"]],
  "73": ["Oraliq masofa", "Oldingi transport keskin tormoz bergan taqdirda to'qnashmaslik kafolatini beradigan masofani va xavfsiz yonlama oraliqni saqlang.", "Oldingi mashinagacha masofa qanday tanlanadi?", ["U keskin tormozlaganda to'qnashmaslik uchun yetarli", "Aynan 10 m", "Iloji boricha yaqin"]],
  "75": ["Sizning tomoningizda to'siq", "To'siq tufayli qarama-qarshi harakat qiyin bo'lsa, to'siq o'z tomonida bo'lgan haydovchi yo'l beradi.", "Tor yo'lda sizning tomoningizda to'siq bor. Nima qilasiz?", ["Qarama-qarshi kelayotganga yo'l beraman", "Birinchi bo'lib o'taman", "Signal chalib o'taman"]],

  // Tezlik
  "77": ["Tezlik sharoitga mos bo'lsin", "Tezlikni oqim, transport va yuk, yo'l va ob-havo, ko'rinishni hisobga olib, chegaradan oshirmasdan tanlang. Xavfni sezsangiz, tezlikni kamaytiring, to'xtang yoki xavfsiz aylanib o'ting.", "Tezlik qanday tanlanadi?", ["Sharoitga mos va chegaradan oshmaydigan", "Ruxsat etilgan eng yuqori", "Oldingi mashinadek"]],
  "78": ["Aholi punktlarida tezlik", "Aholi punktlarida 70 km/soatgacha. Belgi qo'yilgan maktab va maktabgacha ta'lim tashkilotlariga yetmasdan va o'tib 300 m ichida 30 km/soatgacha. Turar joy dahalari va hovlilarda 20 km/soatgacha.", "Maktabdan 300 m ichida tezlik chegarasi qancha?", ["30 km/soat", "50 km/soat", "70 km/soat"]],
  "78b": ["Katta shaharlarda tezlik", "Nukus va Toshkent shaharlarida, viloyat va tuman markazlarida hamda shahar hududlarida 60 km/soatgacha ruxsat etiladi.", "Toshkentda odatdagi maksimal tezlik qancha?", ["60 km/soat", "90 km/soat", "40 km/soat"]],
  "79": ["Aholi punktlaridan tashqarida tezlik", "Aholi punktlaridan tashqarida: yengil va 3,5 t gacha yuk mashinalari 100 km/soat. Shaharlararo avtobus va mikroavtobuslar 90. Boshqa avtobuslar, tirkamali yengil mashinalar, mototsikllar va 3,5 t dan ortiq yuk mashinalari 80. Tirkamali yuk mashinalari 70.", "Yengil avtomobil aholi punktidan tashqarida qancha tezlikda yura oladi?", ["100 km/soatgacha", "120 km/soatgacha", "80 km/soatgacha"]],
  "80": ["Maxsus tezlik chegaralari", "Yukxonasida odam tashiyotgan yuk mashinalari va bolalar guruhini tashiyotgan transport 60 km/soat. Shatakka olgan transport 50 km/soat. Xavfli va katta o'lchamli yuklar DYHXX bilan kelishilgan tezlikda.", "Shatakka olishda tezlik chegarasi qancha?", ["50 km/soat", "70 km/soat", "90 km/soat"]],
  "81": ["Tezlik bo'yicha taqiqlar", "Transport vositasining eng yuqori tezligidan va belgilangan chegaradan oshmang, zaruratsiz juda sekin yurib xalaqit bermang, hodisaning oldini olish zarurati bo'lmasa keskin tormozlamang.", "Zaruratsiz keskin tormozlash mumkinmi?", ["Yo'q", "Ha, achchiq ko'rsatish uchun", "Ha, nam yo'lda"]],

  // Quvib o'tish
  "82": ["Quvib o'tishdan oldin", "Chapga burilish ishorasini yoqing va tekshiring: tasma yetarlicha masofada bo'sh, orqadagi quvib o'tishni boshlamagan, oldindagi ishora bermayapti va quvib o'tilganga xalaqit bermay qaytib kira olasiz.", "Quvib o'tishdan oldin birinchi nima qilinadi?", ["Chap burilish ishorasini yoqib, yo'lni tekshirish", "Signal chalib tezlashish", "Chiziqqa chiqish"]],
  "83": ["Qaysi tomondan o'tish", "Relssiz transportni har ikki tomondan o'zib ketish mumkin, lekin chapga burilish ishorasini berib burilishga kirishgan transport o'ng tomondan o'zib ketiladi.", "Oldingi mashina chapga ishora berib burilmoqda. Qaysi tomondan o'tasiz?", ["O'ng tomondan", "Chap tomondan", "O'tish mumkin emas"]],
  "84": ["Quvib o'tishga to'sqinlik qilmang", "Quvib o'tilayotgan haydovchi tezlikni oshirmasligi yoki boshqa xatti-harakat bilan quvib o'tishga to'sqinlik qilmasligi kerak.", "Sizni quvib o'tishyapti. Nima qilmaslik kerak?", ["Tezlikni oshirish", "Tezlikni saqlash", "O'ngga olish"]],
  "85": ["Quvib o'tgach qaytish", "Quvib o'tishni tugallagach haydovchi ilgari egallagan tasmaga qaytishi shart.", "Quvib o'tgach nima qilinadi?", ["Oldingi tasmaga qaytiladi", "Qarama-qarshi tasmada qolinadi", "To'xtaladi"]],
  "86": ["Quvib o'tish taqiqlangan joylar", "Quvib o'tish tartibga solingan chorrahalarda, tartibga solinmagan chorrahalarda asosiy bo'lmagan yo'lda, ko'prik, yo'l o'tkazgich, estakadalarda va ularning ostida, piyodalar o'tish joylarida, temir yo'l kesishmalarida va ulargacha 100 m, tepalik oxirida va ko'rinish cheklangan joylarda taqiqlanadi.", "Quvib o'tish qayerda taqiqlanadi?", ["Piyodalar o'tish joyida", "Keng to'g'ri yo'lda", "Bo'sh to'xtab turish joyida"]],
  "87": ["Sekin va katta transport", "Aholi punktlaridan tashqarida sekin yoki katta hajmli transportni quvib o'tish qiyin bo'lsa, uning haydovchisi o'ngga olishi, kerak bo'lsa orqasida to'planganlarni o'tkazish uchun to'xtashi kerak.", "Aholi punktidan tashqarida sekin ketyapsiz va orqada navbat to'plandi. Nima qilasiz?", ["O'ngga olaman, kerak bo'lsa to'xtayman", "Tezlashaman", "O'rtada yuraman"]],

  // To'xtash va to'xtab turish
  "88": ["Qayerda to'xtash va to'xtab turish", "Yo'lning o'ng tomonida yo'l yoqasida, u bo'lmasa qatnov qismi chetida to'xtang va to'xtab turing. Aholi punktlarida bir tomonlama yoki har yo'nalishda bitta tasmali tramvaysiz yo'llarda chap tomon ham mumkin.", "Ikki tomonlama yo'lning qaysi tomonida odatda to'xtab turish mumkin?", ["O'ng tomonida", "Chap tomonida", "O'rtasida"]],
  "89": ["Qanday to'xtab turish", "Transportni bir qatorda, qatnov qismi chetiga parallel qo'ying. Kajavasiz ikki g'ildirakli transport xalaqit bermasa ikki qatorda ham mumkin. Trotuar chetida faqat 5.15 belgisi bilan qo'shimcha belgi ruxsat bergan joyda.", "Qatnov qismida mashinalar odatda qanday qo'yiladi?", ["Bir qatorda, chetga parallel", "Burchak ostida", "Ikki qatorda"]],
  "91": ["To'xtash taqiqlangan: yo'llar, tunnel, ko'prik", "Tramvay yo'llarida, temir yo'l kesishmalarida, tunnellarda, har yo'nalishda uchtadan kam tasmali ko'prik va estakadalar ustida va ularning ostida (belgi ruxsat bermasa) to'xtash taqiqlanadi.", "To'xtash qayerda taqiqlanadi?", ["Temir yo'l kesishmasida", "Keng to'xtab turish joyida", "Bo'sh tasmali yo'l chetida"]],
  "91b": ["To'xtash taqiqlangan: o'tish joylari", "Piyodalar o'tish joylarida va ulardan oldin 10 m dan kam masofada, shuningdek velosiped yo'lkasi kesishuvida va undan oldin 10 m dan kam masofada to'xtash taqiqlanadi.", "Piyodalar o'tish joyidan oldin qanchalik yaqin to'xtash mumkin?", ["10 m dan yaqin emas", "Tegib turgunicha", "1 m dan yaqin emas"]],
  "91c": ["To'xtash taqiqlangan: chorrahalar", "Qatnov qismlari kesishmalarida va kesishayotgan qatnov qismi chetidan 30 m dan kam masofada to'xtash taqiqlanadi (uch tomonlama chorrahada yondan tutashgan yo'lning sidirg'a chiziq yoki ajratuvchi mintaqa bilan ajratilgan qarama-qarshi tomoni bundan mustasno).", "Kesishayotgan qatnov qismi chetidan qancha masofada to'xtash taqiqlanadi?", ["30 m dan kam masofada", "5 m dan kam masofada", "100 m dan kam masofada"]],
  "91d": ["To'xtash taqiqlangan: bekatlar", "Yo'nalishli transport bekatlarida va bekatdan oldin va keyin 15 m dan kam masofada to'xtash taqiqlanadi (avtobuslarga xalaqit bermay yo'lovchi chiqarish yoki tushirish bundan mustasno).", "Avtobus bekatiga qanchalik yaqin to'xtash taqiqlanadi?", ["15 m dan kam masofada", "2 m dan kam masofada", "50 m dan kam masofada"]],
  "91e": ["To'xtash taqiqlangan: ko'rinish va oraliq", "Shuningdek, to'xtagan transport bilan sidirg'a chiziq, ajratuvchi mintaqa yoki qarama-qarshi chet orasidagi masofa 3 m dan kam joylarda, ko'rinish 100 m dan kam do'ngliklar va xavfli burilishlarda, svetofor, belgi, chiqish yoki piyodalarga xalaqit beradigan joylarda to'xtash taqiqlanadi.", "Ko'rinish masofasi qanchadan kam joyda to'xtash taqiqlanadi?", ["100 m dan kam", "300 m dan kam", "10 m dan kam"]],
  "92": ["To'xtab turish taqiqlangan", "To'xtash taqiqlangan joylarda, temir yo'l kesishmasining har ikki tomonida 50 m yaqinida, 3.27 — 3.30 belgilari yoki 1.4 va 1.10 chiziqlari ta'sirida to'xtab turish taqiqlanadi. Yuk mashinalarini kechasi yo'l chetida boshqalarga xavf tug'diradigan holatda qoldirish ham taqiqlanadi.", "Temir yo'l kesishmasiga qanchalik yaqin to'xtab turish taqiqlanadi?", ["50 m yaqinida", "5 m yaqinida", "500 m yaqinida"]],
  "93": ["Taqiqlangan joyda majburiy to'xtash", "To'xtash taqiqlangan joyda majburiy to'xtasangiz, transportni yo'l chetiga olib chiqish va o'sha joydan olib ketishning barcha choralarini ko'ring.", "To'xtash taqiqlangan joyda buzilib qoldingiz. Nima qilasiz?", ["Yo'ldan olib chiqish va olib ketishning barcha choralarini ko'raman", "O'sha joyda qoldiraman", "Chiroqlarni o'chirib kutaman"]],
  "94": ["Eshiklarni ochish", "Boshqa yo'l harakati ishtirokchilariga xalaqit beradigan yoki xavf tug'diradigan bo'lsa, transport eshiklarini ochish taqiqlanadi.", "Eshikni ochish qachon taqiqlanadi?", ["Boshqalarga xalaqit bersa yoki xavf tug'dirsa", "Hech qachon", "Faqat kechasi"]],
  "95": ["Mashinani tashlab ketish", "O'z-o'zidan harakatlanib ketishni va o'zi yo'qligida foydalanishni istisno qiladigan ehtiyot choralarini ko'rgandan keyingina haydovchi o'rnini tashlab ketishi mumkin.", "Mashinadan chiqishdan oldin nima qilish kerak?", ["O'z-o'zidan yurib ketishi va foydalanilishini istisno qilish", "Dvigatelni ishlatib qoldirish", "Barcha eshiklarni ochish"]],

  // Chorrahalar
  "96": ["Burilishda piyodalarga yo'l bering", "Chapga yoki o'ngga burilayotgan haydovchi kirayotgan yo'lni kesib o'tayotgan piyodalarga, shuningdek velosiped yo'lkasidan kesib o'tayotgan velosipedchi va individual harakatlanish vositasi haydovchilariga yo'l beradi.", "Chorrahada o'ngga burilganda kimga yo'l berasiz?", ["Kirayotgan yo'lingizni kesib o'tayotgan piyodalarga", "Hech kimga", "Faqat mashinalarga"]],
  "97": ["Chorrahani to'smang", "Tirbandlik tufayli to'xtab, ko'ndalang harakatga to'sqinlik qilsangiz, chorrahaga kirmang. To'xtash chizig'idan o'tib bo'lgan bo'lsangiz, qatnov qismlari kesishmasiga kirmang.", "Chorraha oldida tirbandlik. Nima qilasiz?", ["Ko'ndalang harakatni to'ssam, kirmayman", "Kirib, o'rtada kutaman", "Signal chalaman"]],
  "98": ["Tartibga solingan va solinmagan chorrahalar", "Navbat svetofor yoki tartibga soluvchi bilan boshqarilsa, chorraha tartibga solingan. Miltillovchi sariq, ishlamayotgan svetoforlar yoki tartibga soluvchi bo'lmasa — tartibga solinmagan. Aylanma harakatda aylanadagilar kirayotganlardan ustun.", "Aylanma harakatda kimda ustuvorlik bor?", ["Aylanada harakatlanayotganlarda", "Kirayotganlarda", "Kattaroq transportda"]],
  "99": ["Yashilda chapga burilish", "Ruxsat etuvchi ishorada chapga burilayotgan yoki qayrilib olayotgan haydovchi qarama-qarshi tomondan to'g'riga va o'ngga ketayotganlarga yo'l beradi. Tramvaylar ham shunday.", "Yashilda chapga burilyapsiz. Kimga yo'l berasiz?", ["To'g'riga yoki o'ngga ketayotgan qarama-qarshi transportga", "Hech kimga", "Orqadagilarga"]],
  "100": ["Yashil strelka", "Qizil yoki sariq bilan birga yongan qo'shimcha tarmoqdagi yashil strelka yo'nalishida harakatlanayotgan haydovchi boshqa yo'nalishlardan kelayotgan transportga yo'l beradi.", "Asosiy ishora qizil, siz yashil strelka bo'yicha ketyapsiz. Kimga yo'l berasiz?", ["Boshqa yo'nalishlardan kelayotganlarga", "Hech kimga", "Faqat piyodalarga"]],
  "101": ["Tramvay tartibga solingan chorrahada", "Svetofor tramvay va boshqa transportga bir vaqtda ruxsat bersa, yo'nalishdan qat'i nazar tramvay oldin o'tadi.", "Tramvay va mashina uchun yashil. Kim birinchi?", ["Tramvay", "Mashina", "Tezroqi"]],
  "102": ["Yashilda kirgan, chiqish", "Ruxsat etuvchi ishorada chorrahaga kirgan haydovchi svetofordan qat'i nazar harakatni davom ettiradi, lekin chorraha ichida to'xtash chiziqlari yoki belgisi bo'lgan svetoforlar bo'lsa, ularga amal qiladi.", "Yashilda kirdingiz va ishora almashdi. Nima qilasiz?", ["Chorraha ichida to'xtash chizig'i bo'lmasa, davom etaman", "O'rtada to'xtayman", "Orqaga yuraman"]],
  "103": ["Yashil — bu erkin o'tish emas", "Yashilda chorrahadan o'tishni tugatayotgan transportga va tegishli yo'nalishda o'tishni tugatayotgan piyodalarga yo'l bering.", "Yashil chiroq, lekin piyoda hali o'tmoqda. Nima qilasiz?", ["Piyoda o'tib bo'lishini kutaman", "Yuraman", "Signal chalaman"]],

  // Tartibga solinmagan chorrahalar
  "104": ["Ikkinchi darajali yo'l yo'l beradi", "Teng ahamiyatga ega bo'lmagan yo'llar kesishgan chorrahada ikkinchi darajali yo'ldagi haydovchi asosiy yo'ldagi transportga, uning keyingi yo'nalishidan qat'i nazar, yo'l beradi.", "Siz ikkinchi darajali yo'ldasiz. Kimga yo'l berasiz?", ["Asosiy yo'ldagi transportga", "Hech kimga", "Faqat yuk mashinalariga"]],
  "105": ["Teng yo'llarda o'ngdagiga yo'l bering", "Teng ahamiyatli yo'llar kesishgan chorrahada haydovchi o'ngdan yaqinlashayotgan transportga yo'l beradi. Tramvay yo'nalishidan qat'i nazar oldin o'tadi.", "Teng yo'llar chorrahasida kimga yo'l berasiz?", ["O'ngdan kelayotganga", "Chapdan kelayotganga", "Tezroq kelayotganga"]],
  "106": ["Asosiy yo'l yo'nalishi o'zgaradi", "Asosiy yo'lning yo'nalishi chorrahada o'zgarsa, asosiy yo'ldagi haydovchilar o'zaro teng yo'llar qoidasiga amal qiladi, ikkinchi darajali yo'ldagilar ham.", "Asosiy yo'l chorrahada burilmoqda. Undagi haydovchilar bir-biriga qanday yo'l beradi?", ["Teng yo'llar qoidasi bilan: o'ngdagiga yo'l bering", "Birinchi kelgan o'tadi", "Kattaroq o'tadi"]],
  "107": ["Chorrahada chapga burilish", "Tartibga solinmagan chorrahada teng yo'ldan chapga burilayotgan yoki qayrilib olayotgan haydovchi qarama-qarshi tomondan to'g'riga yoki o'ngga ketayotganlarga yo'l beradi.", "Teng chorrahada chapga burilganda kimga yo'l berasiz?", ["To'g'riga yoki o'ngga ketayotgan qarama-qarshi transportga", "Hech kimga", "Orqadagilarga"]],
  "108": ["Qoplama noma'lum", "Yo'lingizning qoplamasi bor-yo'qligini aniqlay olmasangiz (qorong'i, loy, qor) va imtiyoz belgilari bo'lmasa, o'zingizni ikkinchi darajali yo'lda deb hisoblang.", "Yo'lingizda qoplama bormi-yo'qmi noma'lum, belgilar yo'q. Uni qanday hisoblaysiz?", ["Ikkinchi darajali", "Asosiy", "Boshqasiga teng"]],

  // O'tish joylari va bekatlar
  "109": ["Tartibga solinmagan o'tish joylari", "Tartibga solinmagan piyodalar o'tish joyiga yaqinlashayotgan haydovchi shu yo'nalishda o'tayotgan piyodalarni o'tkazish uchun tezlikni kamaytirishi yoki to'xtashi shart.", "Tartibga solinmagan o'tish joyida piyoda bor. Nima qilasiz?", ["Sekinlashaman yoki to'xtab o'tkazaman", "Signal chalaman", "Tezlashaman"]],
  "110": ["O'tish joyi oldida to'xtagan mashina", "Tartibga solinmagan o'tish joyi oldida transport sekinlashsa yoki to'xtasa, qo'shni tasmalardagi haydovchilar uning oldida piyoda yo'qligiga ishonch hosil qilgachgina davom etadi.", "Qo'shni tasmada mashina o'tish joyi oldida to'xtadi. Nima qilasiz?", ["Piyoda yo'qligiga ishonch hosil qilgach davom etaman", "Tez quvib o'taman", "Signal chalaman"]],
  "111": ["Tartibga solingan o'tish joylari", "Tartibga solingan o'tish joylarida svetofor transportga yashil bo'lsa ham, piyodalarga o'tishni tugatishga imkon bering.", "Sizga yashil, lekin piyodalar hali o'tmoqda. Nima qilasiz?", ["Ularga o'tib bo'lishga imkon beraman", "O'tib ketaman", "Chiroqni miltillataman"]],
  "112": ["O'tish joyida to'xtamang", "O'tish joyidan keyin tirbandlik tufayli piyodalar o'tish joyida to'xtashga majbur bo'lsangiz, unga kirmang.", "O'tish joyidan keyin tirbandlik. O'tish joyida to'xtash mumkinmi?", ["Yo'q, unga kirmayman", "Ha, bir lahzaga", "Ha, avariya chiroqlari bilan"]],
  "113": ["Ko'zi ojiz piyodalar", "Barcha hollarda, o'tish joylaridan tashqarida ham oq hassa bilan ishora berayotgan ko'zi ojiz piyodani o'tkazib yuboring.", "Oq hassali piyoda o'tish joyidan tashqarida kesib o'tmoqda. Nima qilasiz?", ["O'tkazib yuboraman", "Signal chalaman", "Tez o'tib ketaman"]],
  "114": ["Transport bekatlari", "Yo'lovchilar qatnov qismida yoki undagi maydonchada chiqsa va tushsa, bekatda to'xtagan transport eshiklariga borayotgan yoki undan kelayotgan piyodalarga yo'l bering.", "Qatnov qismida to'xtagan tramvayga odamlar ketyapti. Nima qilasiz?", ["Ularga yo'l beraman", "Tez aylanib o'taman", "Signal chalaman"]],
  "115": ["Bolalarni tashish", "«Bolalarni tashish» belgisi bor, avariya ishorasi yoqilgan transport to'xtasa, yaqinlashayotgan haydovchi tezlikni kamaytiradi, zarur bo'lsa to'xtaydi va bolalarni o'tkazadi.", "«Bolalarni tashish» belgili avtobus avariya chiroqlari bilan to'xtadi. Nima qilasiz?", ["Sekinlashaman, kerak bo'lsa to'xtab bolalarni o'tkazaman", "Tez o'tib ketaman", "Signal chalaman"]],
  "1152": ["Yo'nalishli transport tasmalari", "Yo'nalishli transport uchun ajratilgan tasmali yo'lda boshqa transport harakatlana olmaydi (tezkor xizmatlardan tashqari). Yondosh hududga kirish yoki chiqish uchun faqat 50 m masofadagi uzuq chiziqli joygacha, yo'nalishli transportga yo'l berib harakatlanish mumkin.", "Shaxsiy mashina yo'nalishli transport tasmasida yura oladimi?", ["Yo'q, yondosh hududga qoidada belgilangancha kirishdan tashqari", "Ha, bo'sh bo'lsa", "Ha, kechasi"]],

  // Temir yo'l kesishmalari
  "116": ["Temir yo'lni kesib o'tish", "Temir yo'llarni faqat temir yo'l kesishmalaridan, poyezdlarga yo'l berib kesib o'ting.", "Temir yo'lni qayerdan kesib o'tish mumkin?", ["Faqat temir yo'l kesishmalaridan", "Istalgan joydan", "To'siq bo'lmagan joydan"]],
  "117": ["Kesishmaga yaqinlashish", "Kesishma navbatchisi, svetoforlar, belgilar, chiziqlar va shlagbaum holatiga amal qiling va poyezd yaqinlashmayotganiga ishonch hosil qiling.", "Temir yo'lni kesishdan oldin nimaga ishonch hosil qilish kerak?", ["Poyezd yaqinlashmayotganiga", "Shlagbaum bo'yalganiga", "Chiroqlar yoqilganiga"]],
  "118": ["Kirish qachon taqiqlanadi", "Shlagbaum yopiq yoki yopilayotgan bo'lsa, taqiqlovchi ishora yonsa, navbatchi taqiqlasa, tirbandlik kesishmada to'xtatib qo'ysa yoki poyezd ko'rinsa kesishmaga kirish taqiqlanadi.", "Shlagbaum yopilayotir. Nima qilasiz?", ["Kirmayman", "Shoshilib o'taman", "Aylanib o'taman"]],
  "119": ["Qayerda to'xtash", "Taqiqlangan hollarda to'xtash chizig'i, belgi yoki svetofor oldida, ular bo'lmasa shlagbaumga kamida 5 m, shlagbaum bo'lmasa birinchi relsga kamida 10 m qolganda to'xtang.", "Shlagbaumgacha qancha masofada to'xtash kerak?", ["Kamida 5 m", "Kamida 1 m", "Kamida 50 m"]],
  "120": ["Kesishmada to'xtab qolish", "Kesishmada majburan to'xtab qolsangiz, odamlarni tushiring va kesishmani bo'shating. Imkon bo'lsa, ikki kishini yo'l bo'ylab ikki tomonga 1000 m ga yuboring va poyezdga to'xtash ishorasini bering.", "Mashinangiz temir yo'l kesishmasida to'xtab qoldi. Birinchi nima qilasiz?", ["Odamlarni tushirib, kesishmani bo'shataman", "Poyezdni kutaman", "Do'stimga qo'ng'iroq qilaman"]],

  // Avtomagistrallar
  "121": ["Avtomagistraldagi taqiqlar", "Avtomagistralda piyodalar, velosipedlar, mopedlar, traktorlar va tezligi 40 km/soatdan kam transport harakatlanishi, orqaga yurish, ajratuvchi bo'lakdagi uzilishlarga kirib qayrilish, o'rgatish va maydonchalardan tashqarida to'xtash taqiqlanadi. Yuk mashinalari chetki chap tasmada yurmaydi.", "Avtomagistralda nima taqiqlanadi?", ["Orqaga harakatlanish", "Quvib o'tish", "O'ng tasmadan yurish"]],
  "122": ["Avtomagistralda majburiy to'xtash", "Qatnov qismida majburiy to'xtasangiz, transportni Qoidalarga muvofiq belgilang va uni qatnov qismi chetini bildiruvchi chiziqdan o'ngroqdagi maxsus tasmaga olib chiqing.", "Avtomagistralda majburiy to'xtadingiz. Transportni qayerga olib chiqasiz?", ["Chekka chiziqdan o'ngdagi avariya tasmasiga", "O'rta tasmaga", "Chap tasmaga"]],

  // Turar joy dahalari
  "123": ["Turar joy dahalari", "Turar joy dahalarida piyodalar trotuarlar va qatnov qismidan yurishi mumkin. Ular imtiyozga ega, lekin transportga asossiz xalaqit bermasligi kerak.", "Turar joy dahasida qatnov qismida kimda imtiyoz bor?", ["Piyodalarda", "Yengil mashinalarda", "Yuk mashinalarida"]],
  "124": ["Turar joy dahalarida taqiqlar", "Turar joy dahalarida o'rgatish, dvigatel ishlab turgan holda to'xtab turish va 3,5 t dan og'ir yuk mashinalarining ajratilgan joylardan tashqarida to'xtab turishi taqiqlanadi.", "Turar joy dahasida dvigatelni ishlatib turib to'xtab turish mumkinmi?", ["Yo'q", "Ha, qishda", "Ha, qisqa vaqt"]],
  "125": ["Dahalarda ehtiyotkorlik", "Turar joy dahalarida haydovchilar piyodalar xavfsizligini va inshoot, qurilma, o'simliklarning shikastlanmasligini ta'minlashi kerak.", "Turar joy dahasida haydovchilar nimani ta'minlashi shart?", ["Piyodalar xavfsizligini", "Maksimal tezlikni", "Tez yurishni"]],
  "126": ["Dahadan chiqish", "Turar joy dahalaridan chiqishda haydovchilar boshqa yo'l harakati ishtirokchilariga yo'l beradi.", "Turar joy dahasidan yo'lga chiqayotganda kimga yo'l berasiz?", ["Boshqa yo'l harakati ishtirokchilariga", "Hech kimga", "Faqat avtobuslarga"]],

  // Nishabliklar
  "128": ["Tik nishabliklar", "Tik nishablik belgisi bor joyda qarama-qarshi harakat to'siq tufayli qiyinlashsa, nishablikdan pastga harakatlanayotgan haydovchi yo'l beradi.", "Tik nishablikda to'siq bor. Kim yo'l beradi?", ["Nishablikdan pastga ketayotgan", "Yuqoriga ketayotgan", "Tezroq ketayotgan"]],
  "129": ["Nishablikda tormoz ishlamasa", "Tik nishablikda yoki dovonda tormoz tizimi ishlamay qolsa, transportni avariyali holatlar uchun mo'ljallangan yo'lga yo'naltiring.", "Tik tushishda tormoz ishlamay qoldi. Nima qilasiz?", ["Avariyali yo'lga yo'naltiraman", "Dvigatelni o'chiraman", "Chiroqlarni o'chiraman"]],

  // Yo'nalishli transport
  "131": ["Chorrahadan tashqarida tramvay", "Tramvay yo'llari chorrahadan tashqarida qatnov qismini kesib o'tadigan joylarda tramvay relssiz transportga nisbatan imtiyozga ega (depodan chiqish joylari bundan mustasno).", "Tramvay yo'li chorrahadan tashqarida yo'lni kesib o'tadi. Kimda imtiyoz bor?", ["Tramvayda", "Mashinada", "Birinchi kelganda"]],
  "132": ["Ajratilgan tasmalar", "Yo'nalishli transport uchun ajratilgan tasmada boshqa transport harakatlana olmaydi va to'xtay olmaydi. Uzuq chiziq bilan ajratilgan bo'lsa, burilmoqchi transport burilish uchun unga o'tishi mumkin.", "Yo'nalishli transport tasmasida to'xtash mumkinmi?", ["Yo'q", "Ha, bir daqiqaga", "Ha, kechasi"]],
  "133": ["Bekatdan chiqayotgan avtobuslar", "Aholi punktlarida bekatdan harakatni boshlayotgan avtobus va trolleybuslarga yo'l bering. Ularning haydovchilari yo'l berilganiga ishonch hosil qilgachgina harakatni boshlaydi.", "Aholi punktida avtobus bekatdan chiqish uchun ishora berdi. Nima qilasiz?", ["Unga yo'l beraman", "Signal chalaman", "Tezlashaman"]],

  // Yoritish
  "134": ["Chiroqlar qachon kerak", "Qorong'i vaqtda va yomon ko'rinishda, shuningdek tunnellarda mexanik transportda fara chiroqlari, tirkama va shatakka olinganlarda gabarit chiroqlari yoqilgan bo'lishi kerak.", "Tunnelda qaysi chiroqlar yoqilgan bo'lishi kerak?", ["Fara chiroqlari", "Hech qaysi", "Faqat tumanga qarshi"]],
  "135": ["Yaqin nurga o'tish", "Yo'l yoritilgan bo'lsa, qarama-qarshi transportgacha 150 m qolganda va ko'zni qamashtirishi mumkin bo'lgan har qanday holatda uzoq nurdan yaqin nurga o'ting. Ko'zingiz qamashsa, avariya ishorasini yoqing va tezlikni kamaytiring.", "Qarama-qarshi mashinagacha qancha masofada yaqin nurga o'tish kerak?", ["150 m qolganda", "10 m qolganda", "500 m qolganda"]],
  "136": ["Kechasi to'xtab turish", "Qorong'i vaqtda yoritilmagan yo'lda yoki yomon ko'rinishda to'xtagan yoki to'xtab turgan transportda gabarit chiroqlari yoqilgan bo'lishi kerak.", "Mashina kechasi yoritilmagan yo'lda turibdi. Nima yoqilgan bo'lishi kerak?", ["Gabarit chiroqlari", "Hech narsa", "Uzoq nur"]],
  "138": ["Kunduzgi yaqin nur", "Kunduzi yaqin nur kolonnada, yo'lovchili avtobuslarda, bolalarni va xavfli yoki katta o'lchamli yuklarni tashishda, shatakka olishda, kuchli yomg'ir yoki qorda hamda mototsikl va skuterlarda yoqiladi.", "Kunduzi yaqin nur qachon yoqilishi kerak?", ["Kuchli yomg'ir yoki qorda", "Quyoshli kunda", "Hech qachon"]],
  "140": ["Orqa tumanga qarshi chiroqlar", "Tumanga qarshi orqa chiroqlarni faqat yetarlicha ko'rinmaydigan sharoitda qo'llash mumkin. Ularni to'xtash chiroqlariga ulash taqiqlanadi.", "Orqa tumanga qarshi chiroqlar qachon qo'llanadi?", ["Faqat yetarlicha ko'rinmaganda", "Doim", "Har bir burilishda"]],

  // Shatakka olish
  "142": ["Shatakka olish asoslari", "Qattiq yoki egiluvchan ulagich bilan shatakka olish faqat shatakka olingan transport rulida haydovchi bo'lganda amalga oshiriladi (qattiq ulagich izidan yurishni ta'minlaydigan hollar bundan mustasno).", "Shatakka olingan transportda nima bo'lishi kerak?", ["Rulida haydovchi", "Hech kim", "Yukxonada yo'lovchilar"]],
  "143": ["Shatakka olingan transportda odamlar", "Ulagich bilan shatakka olingan avtobus, trolleybus va yuk mashinasi yukxonasida odam tashish, qisman ortish usulida esa har ikkala transportning kabinasi va yukxonasida odam bo'lishi taqiqlanadi.", "Shatakka olinayotgan yuk mashinasi yukxonasida odam tashish mumkinmi?", ["Yo'q", "Ha, bir nechtasini", "Ha, faqat bolalarni"]],
  "144": ["Shatakda masofa", "Egiluvchan ulagichda transport vositalari orasidagi masofa 4 — 6 metr, qattiq ulagichda 4 metrdan ko'p bo'lmasligi kerak.", "Egiluvchan ulagichda transportlar orasidagi to'g'ri masofa qancha?", ["4 — 6 m", "1 m", "10 m"]],
  "145": ["Shatakka olish taqiqlari", "Rul boshqaruvi ishlamayotgan, ikki va undan ko'p transportni, umumiy uzunlik 20 m dan oshsa, ikki g'ildirakli mototsikllarni shatakka olish va yo'l sirpanchiq bo'lsa egiluvchan ulagichda shatakka olish taqiqlanadi.", "Muzlagan yo'lda egiluvchan ulagich bilan shatakka olish mumkinmi?", ["Yo'q", "Ha, sekin", "Ha, kunduzi"]],

  // O'rgatish
  "146": ["Dastlabki darslar", "Transport vositalarini boshqarishni dastlabki o'rgatish yopiq maydonchalarda yoki avtodromlarda o'tkazilishi kerak.", "Dastlabki o'rgatish qayerda o'tkaziladi?", ["Yopiq maydoncha yoki avtodromda", "Avtomagistralda", "Shahar markazida"]],
  "147": ["Yo'llarda o'rgatish", "Yo'llarda o'rgatish faqat o'rgatuvchi ishtirokida dastlabki ko'nikmalarga ega o'rganuvchiga ruxsat etiladi. O'rganuvchi Qoidalarni bilishi va ularga amal qilishi shart.", "Umumiy foydalanishdagi yo'llarda kim o'rgata oladi?", ["Dastlabki ko'nikmali o'rganuvchi bilan o'rgatuvchi", "Do'st", "Hech kim"]],
  "149": ["Minimal yosh", "O'quv muddati yakunida «A» uchun 16, «B» va «C» uchun 18, «BE» va «CE» uchun 19, «D», «DE», tramvay va trolleybus uchun 21 yoshga to'lgan bo'lish kerak.", "«B» toifasi uchun minimal yosh?", ["18", "16", "21"]],
  "150": ["O'quv transporti jihozi", "O'qitish transporti «Boshqarishni o'rgatish transport vositasi» belgisi, o'rgatuvchi uchun ilashish va tormozning qo'shimcha tepkilari, orqani ko'rsatuvchi ko'zgu hamda yo'nalishni nazorat qiluvchi GPS bilan jihozlanishi kerak.", "O'quv mashinasida nima bo'lishi shart?", ["O'rgatuvchi uchun qo'shimcha tepkilar", "Sirena", "Tirkama"]],

  // Odam tashish
  "157": ["Harakatdan oldin", "Harakatni boshlashdan oldin haydovchi yo'lovchilarga xavfsizlik choralari, chiqish, tushish va joylashish tartibini tushuntiradi va ularni xavfsiz tashish shart-sharoiti ta'minlanganiga ishonch hosil qiladi.", "Harakatdan oldin haydovchi nima qiladi?", ["Yo'lovchilarga xavfsizlikni tushuntiradi", "Darhol yuradi", "Musiqa qo'yadi"]],
  "158": ["Chiqish va tushish", "Transport to'liq to'xtagach haydovchi yo'lovchilarning chiqishi va tushishida xavfsizlikni ta'minlaydi, eshiklar yopilgach yuradi va to'liq to'xtamaguncha ochmaydi.", "Haydovchi qachon harakatni boshlashi mumkin?", ["Eshiklar yopilganda", "Yo'lovchilar chiqayotganda", "Istalgan paytda"]],
  "159": ["Odam tashish taqiqlari", "Kabinadan tashqarida (maxsus yuk mashinalaridan tashqari), bolalarni yuk mashinasi yukxonasida, texnik tavsifnomadagidan ko'p odamni, 12 yoshgacha bolalarni mototsikl orqa o'rindig'ida va bolalar uchun maxsus qurilmasiz old o'rindiqda tashish taqiqlanadi.", "12 yoshgacha bolani mototsiklning orqa o'rindig'ida tashish mumkinmi?", ["Yo'q", "Ha, shlem bilan", "Ha, qisqa masofaga"]],

  // Yuk tashish
  "161": ["Yukni tekshiring", "Harakatni boshlashdan oldin yukning to'g'ri joylashganiga va mahkamlanganiga ishonch hosil qiling va harakatlanishda uning holatini kuzating.", "Harakatdan oldin haydovchi yukning qanday ekaniga ishonch hosil qilishi kerak?", ["To'g'ri joylashgan va mahkamlangan", "Og'ir", "Yo'ldan ko'rinib turadi"]],
  "162": ["Xavfsiz yuk", "Yuk haydovchining ko'rishini cheklamasligi, boshqarishni qiyinlashtirmasligi, chiroqlar, raqamlar va qo'l ishoralarini to'smasligi, shovqin, chang va iflos qilmasligi kerak. Yengil mashina tomidagi yuk balandligi 1 m, uzunligi gabaritdan 0,5 m dan oshmasin.", "Yengil mashina tomidagi yuk balandligi qancha bo'lishi mumkin?", ["1 m gacha", "3 m gacha", "5 m gacha"]],
  "163": ["Katta o'lchamli yukni belgilash", "Oldi yoki orqasi tomonga 1 m dan, yon tomonga 0,4 m dan ortiq chiqib turgan yuk «Katta o'lchamli yuk» belgisi bilan, qorong'ida esa chiroq yoki yorug'lik qaytargich bilan belgilanadi.", "Yuk transport orqasidan 1,5 m chiqib turibdi. Nimani ko'rsatish kerak?", ["«Katta o'lchamli yuk» belgisini", "Hech narsani", "Faqat tomda bayroqcha"]],
  "164": ["Katta o'lchamli transportni kelishish", "Eni 2,55 m dan, balandligi 4 m dan, uzunligi 12 m (yakka) yoki 20 m (avtopoyezd) dan ortiq yoki yuki 2 m dan ko'p chiqib turgan transportning harakatlanishi DYHXX bilan kelishilishi shart.", "Balandligi 4 m dan ortiq transport yo'lda yurmoqchi. Nima qilish kerak?", ["DYHXX bilan kelishish", "Hech narsa", "Kechasi yurish"]],

  // Velosipedchilar va IHV
  "165": ["Minimal yosh", "Yo'lda velosiped, arava boshqarish va hayvon haydash 14 yoshdan, moped, skuter va kichik hajmdagi mototransport boshqarish 16 yoshdan ruxsat etiladi.", "Mopedni necha yoshdan boshqarish mumkin?", ["16 yoshdan", "12 yoshdan", "14 yoshdan"]],
  "166": ["Velosipedchilar o'ngda yuradi", "Velosiped, moped va aravalar chetki o'ng bo'lakda, iloji boricha o'ngda, bir qatorda harakatlanadi. Piyodalarga xalaqit bermasa yo'l yoqasidan ham mumkin.", "Velosipedchilar qatnov qismida qanday yuradi?", ["O'ng chetda bir qatorda", "Ikkitadan", "O'rtada"]],
  "167": ["Velosiped jihozi", "Velosipedda tovushli ishora va soz tormoz bo'lishi kerak. Qorong'ida old tomonda oq chiroq yoki nur qaytargich, orqada qizil, yonlarda zarg'aldoq yoki qizil nur qaytargich. Velosiped yo'lkasiz qatnov qismida qorong'ida nur qaytaruvchi kiyim kiyiladi.", "Velosipedning orqa chirog'i qanday rangda bo'lishi kerak?", ["Qizil", "Oq", "Ko'k"]],
  "168": ["Velosipedchilarga taqiqlar", "Velosipedchilar rulni ushlamasdan yoki bir qo'lda (ishoradan tashqari) yurishi, odam tashishi (maxsus o'rindiqda 7 yoshgacha bola bundan mustasno), velosiped yo'lkasi bo'lsa qatnov qismidan yurishi taqiqlanadi. Yo'lni velosipedni yetaklab kesib o'tiladi.", "Velosipedda rulni ushlamasdan yurish mumkinmi?", ["Yo'q", "Ha, to'g'ri yo'lda", "Ha, sekin"]],
  "169": ["Velosiped yo'lkasi kesishuvi", "Chorrahadan tashqaridagi tartibga solinmagan kesishuvda velosipedchi yo'ldagi transportga yo'l beradi. Velosiped yo'lkasi trotuar bilan kesishsa, velosipedchi piyodaga yo'l beradi.", "Velosiped yo'lkasi trotuarni kesib o'tadi. Kim yo'l beradi?", ["Velosipedchi", "Piyoda", "Tezroq ketayotgani"]],
  "pmd122": ["IHV: tezlik", "Elektrosamokat va shunga o'xshash vositalarni boshqaruvchilar Qoidalarga qat'iy rioya qiladi, trotuar va yo'lkalarda 10 km/soatdan, ular bo'lmasa yo'lning o'ng chetida 20 km/soatdan oshirmay harakatlanadi.", "Elektrosamokat haydovchisi trotuarda qancha tezlikda yura oladi?", ["10 km/soatgacha", "30 km/soatgacha", "50 km/soatgacha"]],
  "pmd123": ["IHV va piyodalar", "Velosiped tasmasi yoki birgalikdagi yo'lakda elektrosamokat piyodalarga xavf tug'dirsa, haydovchi tushishi yoki tezlikni piyoda tezligiga tushirishi kerak. U yerda piyodalar doim ustun.", "Birgalikdagi yo'lakda elektrosamokat va piyoda uchrashdi. Kimda imtiyoz bor?", ["Piyodada", "Samokat haydovchisida", "Tezroqda"]],

  // Transport vositalari
  "176": ["Taniqlik belgilari", "Haydovchilik staji 2 yildan kam haydovchilar orqada qora «!» tushirilgan sariq kvadrat qo'yadi. Bolalar guruhini tashishda old va orqada belgi qo'yiladi. Majburiy to'xtashda uchburchak belgi qo'llaniladi.", "Staji 2 yildan kam haydovchi nimani ko'rsatishi kerak?", ["Qora «!» li sariq kvadratni", "Qizil uchburchakni", "Hech narsani"]],

  // Chiziqlar (2-ilova)
  "m1.1": ["Sidirg'a chiziq 1.1", "1.1 chiziq qarama-qarshi oqimlarni ajratadi, xavfli joylar, qatnov qismi chetini va to'xtab turish joyi chegarasini bildiradi. Uni bosib o'tish taqiqlanadi (qatnov qismi chetini bildirganidan tashqari).", "Sidirg'a 1.1 chiziqni bosib o'tish…", ["Taqiqlanadi", "Quvib o'tish uchun ruxsat", "Kechasi ruxsat"]],
  "m1.3": ["Qo'sh sidirg'a chiziq 1.3", "1.3 chiziq to'rt va undan ortiq tasmali yo'llarda qarama-qarshi oqimlarni ajratadi. Uni bosib o'tish taqiqlanadi.", "1.3 chiziq nechta tasmali yo'llarda oqimlarni ajratadi?", ["To'rt va undan ortiq", "Bitta", "Ikkita"]],
  "m1.4": ["Sariq chekka chiziq 1.4", "Qatnov qismi chetidagi yoki to'siq ustidagi sariq 1.4 chiziq (yakka yoki 3.27 belgisi bilan) to'xtashni taqiqlaydi.", "Yo'l chetidagi sariq chiziq nimani anglatadi?", ["To'xtash taqiqlanadi", "To'xtab turish mumkin", "Velosiped tasmasi"]],
  "m1.5": ["Uzuq chiziq 1.5", "1.5 chiziq ikki yoki uch tasmali yo'llarda qarama-qarshi oqimlarni yoki bir yo'nalishli tasmalarni ajratadi. Uni istalgan tomondan bosib o'tish mumkin.", "Uzuq 1.5 chiziqni…", ["Istalgan tomondan bosib o'tish mumkin", "Hech qachon bosib o'tib bo'lmaydi", "Faqat chapdan bosib o'tish mumkin"]],
  "m1.9": ["Reversiv chiziq 1.9", "1.9 chiziq reversiv tasmalar chegarasini belgilaydi. Reversiv svetofor o'chiq bo'lsa, uni faqat haydovchining o'ng tomonida bo'lsa bosib o'tish mumkin va darhol undan o'ngga o'tish kerak.", "Reversiv svetofor o'chiq. 1.9 chiziqni qachon bosib o'tish mumkin?", ["Faqat u o'ng tomoningizda bo'lsa", "Doim", "Hech qachon"]],
  "m1.10": ["Sariq chiziq 1.10", "Sariq 1.10 chiziq (yakka yoki 3.28 belgisi bilan) qatnov qismi chetida yoki to'siq ustida to'xtab turishni taqiqlaydi.", "Sariq 1.10 chiziq nimani anglatadi?", ["To'xtab turish taqiqlanadi", "Quvib o'tish taqiqlanadi", "Tezlik cheklovi"]],
  "m1.11": ["1.11 chiziq", "1.11 chiziq qayta tizilishga faqat bir tomondan ruxsat etilgan joylarda oqimlarni ajratadi. Uzuq tomondan bosib o'tish mumkin, sidirg'a tomondan faqat quvib yoki aylanib o'tishni tugatayotganda.", "1.11 chiziqni sidirg'a tomondan qachon bosib o'tish mumkin?", ["Faqat quvib yoki aylanib o'tishni tugatayotganda", "Doim", "Hech qachon"]],
  "m1.12": ["To'xtash chizig'i 1.12", "1.12 to'xtash chizig'i «To'xtang» belgisi yoki svetofor yoxud tartibga soluvchining taqiqlovchi ishorasida to'xtash kerak bo'lgan joyni ko'rsatadi.", "Qizil chiroqda qayerda to'xtaysiz?", ["1.12 chiziq oldida", "Chiziq ustida", "Chiziqdan keyin"]],
  "m1.14": ["Zebra 1.14", "1.14.1 yoki 1.14.2 «zebra» piyodalar o'tish joyini belgilaydi. Oq-qizil 1.14.4 maktablar oldidagi o'tish joyini bildiradi.", "Qaysi chiziq piyodalar o'tish joyini ko'rsatadi?", ["«Zebra» chiziqlari", "Bitta uzuq chiziq", "Sariq chekka chiziq"]],
  "m-conflict": ["Belgi va chiziq zid bo'lsa", "Yo'l belgilari va chiziqlarning ma'nolari zid kelsa, belgilarga amal qiling. Vaqtincha va doimiy chiziqlar zid kelsa, vaqtinchalariga. Ko'rinmaydigan chiziqlar o'rniga belgilar o'rnatiladi.", "Belgi va chiziq bir-biriga zid. Kimga amal qilasiz?", ["Belgiga", "Chiziqqa", "Oldingi mashinaga"]],

  // Texnik shartlar (3-ilova)
  "t-tyre": ["Shina protektori chuqurligi", "Protektor qoldiq balandligi 1,6 mm dan kam bo'lsa, yengil mashinadan foydalanish taqiqlanadi. Og'ir yuk mashinalari va tirkamalar uchun 1,0 mm, avtobuslar uchun 2,0 mm, mototsikllar uchun 0,8 mm.", "Yengil mashina shinasi protektorining minimal chuqurligi?", ["1,6 mm", "0,5 mm", "3 mm"]],
  "t-kit": ["Majburiy jihozlar", "Yengil va yuk mashinalarida tibbiyot qutichasi, o't o'chirgich, to'xtash belgisi (yoki miltillovchi qizil chiroq) va nur qaytargichli kamzul bo'lishi shart. Avtobuslarda ikkita o't o'chirgich va bolg'acha.", "Mashinada qaysi buyum bo'lishi shart?", ["O't o'chirgich", "Belkurak", "Shatak arqoni"]],
  "t-glass": ["Oyna tusi", "Old va yon oynalarning yorug'lik o'tkazuvchanligi kamida 70 foiz bo'lishi kerak (lyuk va ruxsatnoma bilan qoraytirilgan oynalar bundan mustasno).", "Old oynalar kamida qancha yorug'lik o'tkazishi kerak?", ["70 foiz", "30 foiz", "50 foiz"]],
};
